import json, subprocess, sys, os
base = '/Users/gabe/.cache/caliper/corpora/repos/'
corpora = ['mantine/packages/@mantine/core/src', 'chakra-ui/packages/react/src', 'shadcn-ui/apps/v4', 'ant-design/components',
           'react-spectrum/packages']
bins = {'main': '/tmp/claude-501/oxc6/docgen-main', 'new': '/tmp/claude-501/oxc6/docgen-new'}
out = '/tmp/claude-501/oxc6/corpus'
os.makedirs(out, exist_ok=True)


def run(bin_path, corpus, dest):
    r = subprocess.run([bin_path, 'extract', '--json', '--quiet', '--no-cache', base + corpus], capture_output=True, text=True)
    open(dest, 'w').write(r.stdout)
    return r.returncode


def strip(value):
    if isinstance(value, dict):
        return {k: strip(v) for k, v in value.items() if k != 'stats'}
    if isinstance(value, list):
        return [strip(v) for v in value]
    return value


def diagnostics(data):
    found = []
    def walk(value):
        if isinstance(value, dict):
            if 'code' in value and 'severity' in value:
                found.append(value)
            for v in value.values():
                walk(v)
        elif isinstance(value, list):
            for v in value:
                walk(v)
    walk(data)
    return found


for corpus in corpora:
    key = corpus.split('/')[0]
    results = {}
    for name, path in bins.items():
        dest = f'{out}/{key}-{name}.json'
        code = run(path, corpus, dest)
        try:
            data = json.load(open(dest))
        except Exception as e:
            print(f'{key} {name}: exit {code}, unparsable: {e}'); data = None
        results[name] = (code, data)
    (mc, md), (nc, nd) = results['main'], results['new']
    if md is None or nd is None:
        continue
    bad = {n: sorted({(d['code'], d['severity']) for d in diagnostics(dd) if str(d['code']).upper().replace('_', '') == 'SEMANTICBACKEND' and str(d['severity']).lower() != 'info'})
           for n, dd in (('main', md), ('new', nd))}
    new_codes = sorted({(d['code'], d['severity'], d.get('message', '')[:160]) for d in diagnostics(nd)} - {(d['code'], d['severity'], d.get('message', '')[:160]) for d in diagnostics(md)})
    same = strip(md) == strip(nd)
    print(f'{key}: exit main {mc} new {nc}; identical (stats dropped): {same}; non-info SEMANTIC_BACKEND {bad}; '
          f'components main {len(md.get("components", md)) if isinstance(md, dict) else "?"} new {len(nd.get("components", nd)) if isinstance(nd, dict) else "?"}')
    for entry in new_codes[:10]:
        print('   new diagnostic:', entry)

