src = '/Users/gabe/.cache/caliper/corpora/repos/chakra-ui/packages/react/src'
bins = {'fbd83a0d': '/tmp/claude-501/oxc6/docgen-fbd83a0d', 'new': '/tmp/claude-501/oxc6/docgen-new'}
modes = {'no-checker': ['--no-checker'], 'checker': []}
for mode, extra in modes.items():
    counts = {name: [] for name in bins}
